for c in [3, 7, 11, 15]:
    for r in range(8):
        output[r][c] = 2

# Main diagonal (row = col where not a divider)
for i in range(8):
    if output[i][i] == 7:
        output[i][i] = 3

print("Single main diagonal:")
for row in output:
    print(" ".join(map(str, row)))

